-- OVERGREEN CLOUD V93 — AUDIT LOG COMPLETO\nbegin;\n\ncreate table if not exists public.audit_log (\n  id bigserial primary key,\n  created_at timestamptz not null default now(),\n  actor_id uuid, actor_name text, actor_email text,\n  action text not null, section text not null default 'system',\n  entity_type text, entity_id text, description text,\n  old_data jsonb, new_data jsonb,\n  details jsonb not null default '{}'::jsonb,\n  client jsonb not null default '{}'::jsonb\n);\ncreate index if not exists audit_log_created_at_idx on public.audit_log(created_at desc);\ncreate index if not exists audit_log_actor_idx on public.audit_log(actor_id,created_at desc);\ncreate index if not exists audit_log_section_idx on public.audit_log(section,created_at desc);\nalter table public.audit_log enable row level security;\nrevoke insert,update,delete on public.audit_log from authenticated,anon;\ndrop policy if exists audit_log_admin_select on public.audit_log;\ncreate policy audit_log_admin_select on public.audit_log for select to authenticated using (exists(select 1 from public.profiles p where p.id=auth.uid() and p.ruolo='admin'));\n\ncreate or replace function public.audit_actor_name() returns text language sql security definer set search_path=public as $$\n  select coalesce((select p.nome from public.profiles p where p.id=auth.uid()),(select u.email from auth.users u where u.id=auth.uid()),'Sistema/SQL')\n$$;\ncreate or replace function public.audit_actor_email() returns text language sql security definer set search_path=public as $$\n  select (select u.email from auth.users u where u.id=auth.uid())\n$$;\n\ncreate or replace function public.audit_table_change() returns trigger language plpgsql security definer set search_path=public as $$\ndeclare v_section text; v_id text; v_old jsonb; v_new jsonb;\nbegin\n  v_section:=case TG_TABLE_NAME when 'stores' then 'stores' when 'schedules' then 'schedule' when 'schedule_items' then 'schedule' when 'schedule_members' then 'schedule' when 'interventions' then 'interventions' when 'intervention_workers' then 'interventions' when 'extras' then 'extras' when 'extra_workers' then 'extras' when 'attachments' then 'attachments' when 'signature_sheets' then 'signatures' when 'profiles' then 'users' else 'system' end;\n  if TG_OP='DELETE' then v_old=to_jsonb(OLD);v_new=null;v_id=coalesce(v_old->>'id',''); else v_new=to_jsonb(NEW);v_id=coalesce(v_new->>'id','');if TG_OP='UPDATE' then v_old=to_jsonb(OLD);end if;end if;\n  insert into public.audit_log(actor_id,actor_name,actor_email,action,section,entity_type,entity_id,description,old_data,new_data)\n  values(auth.uid(),public.audit_actor_name(),public.audit_actor_email(),TG_OP,v_section,TG_TABLE_NAME,nullif(v_id,''),TG_OP||' su '||TG_TABLE_NAME,v_old,v_new);\n  return coalesce(NEW,OLD);\nend $$;\n\n-- Trigger su tutte le tabelle operative dell'app.\ndo $$ declare t text; begin\n  foreach t in array array['stores','schedules','schedule_items','schedule_members','interventions','intervention_workers','extras','extra_workers','attachments','signature_sheets','profiles'] loop\n    execute format('drop trigger if exists trg_audit_%I on public.%I',t,t);\n    execute format('create trigger trg_audit_%I after insert or update or delete on public.%I for each row execute function public.audit_table_change()',t,t);\n  end loop;\nend $$;\n\n-- Storage: registra upload/cancellazioni nel bucket documenti.\ncreate or replace function public.audit_storage_change() returns trigger language plpgsql security definer set search_path=public,storage as $$\ndeclare r record; act text;\nbegin\n  r:=coalesce(NEW,OLD);\n  if r.bucket_id<>'documenti' then return coalesce(NEW,OLD);end if;\n  act:=case when TG_OP='INSERT' then 'UPLOAD' when TG_OP='DELETE' then 'DELETE' else TG_OP end;\n  insert into public.audit_log(actor_id,actor_name,actor_email,action,section,entity_type,entity_id,description,new_data)\n  values(auth.uid(),public.audit_actor_name(),public.audit_actor_email(),act,'storage','storage_object',r.id::text,act||' file '||r.name,to_jsonb(r));\n  return coalesce(NEW,OLD);\nend $$;\ndrop trigger if exists trg_audit_storage_documents on storage.objects;\ncreate trigger trg_audit_storage_documents after insert or update or delete on storage.objects for each row execute function public.audit_storage_change();\n\n-- Eventi frontend che non cambiano tabelle: login, logout, apertura pagine.\ncreate or replace function public.write_client_audit(p_action text,p_section text,p_description text,p_details jsonb default '{}'::jsonb,p_client jsonb default '{}'::jsonb) returns bigint language plpgsql security definer set search_path=public as $$\ndeclare v_id bigint;begin\n if auth.uid() is null then raise exception 'Authentication required';end if;\n insert into public.audit_log(actor_id,actor_name,actor_email,action,section,entity_type,entity_id,description,details,client)\n values(auth.uid(),public.audit_actor_name(),public.audit_actor_email(),p_action,p_section,'client_event',auth.uid()::text,p_description,coalesce(p_details,'{}'::jsonb),coalesce(p_client,'{}'::jsonb)) returning id into v_id;\n return v_id;end $$;\nrevoke all on function public.write_client_audit(text,text,text,jsonb,jsonb) from public;\ngrant execute on function public.write_client_audit(text,text,text,jsonb,jsonb) to authenticated;\n\ncommit;\n